problem.solution:
public class DoubleValue {
    public static void main(String[] args) {
        int number = 5;
        int doubled = doubleValue(number);
        System.out.println("Original: " + number);
        System.out.println("Doubled: " + doubled);
    }

    public static int doubleValue(int value) {
        return value * 2;
    }
}
